+// API keys, role permissions and the audit log of data changes.
+import { AppError } from "../errors.js";
+
+export const ROLES = ["viewer", "cook", "manager"];
+
+const COOK_POST_PATHS = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Finds the API key record for a bearer token, or throws unauthorized. */
+export function authenticate(store, token) {
+  if (!token) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks that `apiKey` may call `method` on `path`, or throws forbidden. */
+export function authorize(apiKey, method, path) {
+  const { role } = apiKey;
+  if (role === "manager") return;
+  if (role === "viewer" && method === "GET" && path !== "/audit") return;
+  if (role === "cook") {
+    if (method === "GET" && path !== "/audit") return;
+    if (method === "POST" && COOK_POST_PATHS.some((re) => re.test(path))) return;
+  }
+  throw new AppError("forbidden");
+}
+
+/** Records an audit entry for a request that changed data. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse().sort((a, b) => b.at.localeCompare(a.at));
+}
